using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;

namespace MyMcpServer;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the MCP SDK resolves this from the DI container
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Gets the current weather forecast for a city.")]
    public async Task<string> GetWeather(
        [Description("City name, e.g. 'Seattle'")] string city,
        CancellationToken cancellationToken = default)
    {
        var response = await _httpClient.GetAsync(
            $"https://api.example.com/weather?city={Uri.EscapeDataString(city)}",
            cancellationToken);

        response.EnsureSuccessStatusCode();

        var forecast = await response.Content.ReadFromJsonAsync<WeatherResponse>(
            cancellationToken: cancellationToken);

        return $"{city}: {forecast?.Temperature}°F, {forecast?.Condition}";
    }

    [McpServerTool, Description("Gets a 5-day forecast for a city.")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        [Description("Number of days (1-5)")] int days = 5,
        CancellationToken cancellationToken = default)
    {
        var response = await _httpClient.GetAsync(
            $"https://api.example.com/forecast?city={Uri.EscapeDataString(city)}&days={days}",
            cancellationToken);

        response.EnsureSuccessStatusCode();

        var result = await response.Content.ReadAsStringAsync(cancellationToken);
        return result;
    }
}

public record WeatherResponse(double Temperature, string Condition);

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using MyMcpServer;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddHttpClient<WeatherTools>(client =>
{
    client.DefaultRequestHeaders.Add("Accept", "application/json");
    // Configure base address, auth headers, timeouts, etc.
});

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

